import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"未濟","description":"周易正义 - 未濟","frontmatter":{"title":"未濟","description":"周易正义 - 未濟"},"headers":[],"relativePath":"zh/classics/zhengyi/064.md","filePath":"zh/classics/zhengyi/064.md"}'),l={name:"zh/classics/zhengyi/064.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>火水未济</p></blockquote><blockquote><p>卦辞：亨，小狐汔济，濡其尾，无攸利。</p></blockquote><blockquote><p>彖曰：未济亨，柔得中也。小狐汔济，未出中也。濡其尾，无攸利，不续终也。虽不当位，刚柔应也。</p></blockquote><h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未济，亨”者，“未济”者，未能济渡之名也。未济之时，小才居位，不能建功立德，拔难济险。若能执柔用中，委任贤哲，则未济有可济之理，所以得通，故曰“未济，亨”。“小狐汔济，濡其尾，无攸利”者，汔者，将尽之名。小才不能济难，事同小狐虽难渡水，而无馀力，必须水汔，方可涉川。未及登岸，而濡其尾，济不免濡，岂有所利？故曰“小狐汔济，濡其尾，无攸利”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="未济-亨-柔得中也。-​" tabindex="-1">“未济，亨”，柔得中也。 ​ <a class="header-anchor" href="#未济-亨-柔得中也。-​" aria-label="Permalink to ““未济，亨”，柔得中也。 ​”">​</a></h3><p>王弼：以柔处中，不违刚也。能纳刚健，故得亨也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就六五以柔居中，下应九二，释“未济”所以得“亨”，柔而得中，不违刚也。与二相应，纳刚自辅，故於未济之世，终得亨通也。</p><h3 id="小狐汔济-未出中也。-​" tabindex="-1">“小狐汔济”，未出中也。 ​ <a class="header-anchor" href="#小狐汔济-未出中也。-​" aria-label="Permalink to ““小狐汔济”，未出中也。 ​”">​</a></h3><p>王弼：小狐不能涉大川，须汔然后乃能济。处未济之时，必刚健拔难，然后乃能济，汔乃能济，未能出险之中。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“小狐汔济，未出中也”者，释小狐涉川，所以必须水汔乃济，以其力薄，未能出险之中故也。</p><h3 id="濡其尾-无攸利-不续终也。-​" tabindex="-1">“濡其尾，无攸利”，不续终也。 ​ <a class="header-anchor" href="#濡其尾-无攸利-不续终也。-​" aria-label="Permalink to ““濡其尾，无攸利”，不续终也。 ​”">​</a></h3><p>王弼：小狐虽能渡而无馀力。将济而濡其尾，力竭於斯，不能续终。险难犹未足以济也。济未济者，必有馀力也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：濡尾力竭，不能相续而终，至於登岸，所以无攸利也。</p><h3 id="虽不当位-刚柔应也。-​" tabindex="-1">虽不当位，刚柔应也。 ​ <a class="header-anchor" href="#虽不当位-刚柔应也。-​" aria-label="Permalink to “虽不当位，刚柔应也。 ​”">​</a></h3><p>王弼：位不当，故未济。刚柔应，故可济。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“虽不当位，刚柔应”者，重释未济之义，凡言未者，今日虽未济，复有可济之理。以其不当其位，故即时未济；刚柔皆应，是得相拯，是有可济之理。故称“未济”，不言“不济”也。</p><h2 id="《象》曰-火在水上-未济。君子以慎辨物居方。-​" tabindex="-1">《象》曰：火在水上，未济。君子以慎辨物居方。 ​ <a class="header-anchor" href="#《象》曰-火在水上-未济。君子以慎辨物居方。-​" aria-label="Permalink to “《象》曰：火在水上，未济。君子以慎辨物居方。 ​”">​</a></h2><p>王弼：辨物居方，令物各当其所也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“火在水上未济”者，火在水上，不成烹饪，未能济物。故曰“火在水上，未济”。“君子以慎辨物居方”者，君子见未济之时，刚柔失正，故用慎为德，辨别众物，各居其方，使皆得安其所，所以济也。</p><h2 id="初六-濡其尾-吝。-​" tabindex="-1">初六：濡其尾，吝。 ​ <a class="header-anchor" href="#初六-濡其尾-吝。-​" aria-label="Permalink to “初六：濡其尾，吝。 ​”">​</a></h2><p>王弼：处未济之初，最居险下，不可以济者也。而欲之其应，进则溺身。未济之始，始於既济之上六也。濡其首犹不反，至於濡其尾，不知纪极者也。然以阴处下，非为进亢，遂其志者也。困则能反，故不曰凶。事在已量，而必困乃反，顽亦甚矣，故曰“吝”也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“初六”至“吝”。○正义曰：初六处未济之初，最居险下，而欲上之其应，进则溺身，如小狐之渡川，濡其尾也。未济之始，始於既济之上六也。既济上六，但云“濡其首”，言始入於难，未没其身。此言“濡其尾”者，进不知极，巳没其身也。然以阴处下，非为进亢，遂其志者也。困则能反，故不曰凶。不能豫昭事之几萌，困而后反，顽亦甚矣，故曰“吝”也。○注“不知纪极”。○正义曰：“不知纪极”者，《春秋传》曰“聚敛积实，不知纪极，谓之饕餮”，言无休已也。</p><h3 id="《象》曰-濡其尾-亦不知极也。-​" tabindex="-1">《象》曰：“濡其尾”，亦不知极也。 ​ <a class="header-anchor" href="#《象》曰-濡其尾-亦不知极也。-​" aria-label="Permalink to “《象》曰：“濡其尾”，亦不知极也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“亦不知极”者，未济之初，始於既济之上六，濡首而不知，遂濡其尾，故曰“不知极”也。</p><h2 id="九二-曳其轮-贞吉。-​" tabindex="-1">九二：曳其轮，贞吉。 ​ <a class="header-anchor" href="#九二-曳其轮-贞吉。-​" aria-label="Permalink to “九二：曳其轮，贞吉。 ​”">​</a></h2><p>王弼：体刚履中，而应於五，五体阴柔，应与而不自任者也。居未济之时，处险难之中，体刚中之质，而见任与，拯救危难，经纶屯蹇者也。用健拯难，靖难在正，而不违中，故“曳其轮，贞吉”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“曳其轮，贞吉”者，九二居未济之时，处险难之内，体刚中之质，以应於五。五体阴柔，委任於二，令其济难者也。经纶屯蹇，任重忧深，故曰“曳其轮”。“曳其轮”者，言其劳也。靖难在正，然后得吉，故曰“曳其轮，贞吉”也。</p><h3 id="《象》曰-九二-贞吉-中以行正也。-​" tabindex="-1">《象》曰：“九二”“贞吉”，中以行正也。 ​ <a class="header-anchor" href="#《象》曰-九二-贞吉-中以行正也。-​" aria-label="Permalink to “《象》曰：“九二”“贞吉”，中以行正也。 ​”">​</a></h3><p>王弼：位虽不正，中以行正也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中以行正”者，释九二失位而称贞吉者，位虽不正，以其居中，故能行正也。</p><h2 id="六三-未济-征凶。利涉大川。-​" tabindex="-1">六三：未济，征凶。利涉大川。 ​ <a class="header-anchor" href="#六三-未济-征凶。利涉大川。-​" aria-label="Permalink to “六三：未济，征凶。利涉大川。 ​”">​</a></h2><p>王弼：以阴之质，失位居险，不能自济者也。以不正之身，力不能自济，而求进焉，丧其身也。故曰“征凶”也。二能拯难，而已比之，弃已委二，载二而行，溺可得乎？何忧未济，故曰“利涉大川”。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未济征凶”者，六三以阴柔之质，失位居险，不能自济者也。身既不能自济，而欲自进求济，必丧其身。故曰“未济，征凶”也。“利涉大川”者，二能拯难，而已比之，若能弃已委二，则没溺可免，故曰“利涉大川”。</p><h3 id="《象》曰-未济-征凶-位不当也。-​" tabindex="-1">《象》曰：“未济，征凶”，位不当也。 ​ <a class="header-anchor" href="#《象》曰-未济-征凶-位不当也。-​" aria-label="Permalink to “《象》曰：“未济，征凶”，位不当也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位不当”者，以不当其位故有征则凶。</p><h2 id="九四-贞吉-悔亡。震用伐鬼方-三年有赏于大国。-​" tabindex="-1">九四：贞吉，悔亡。震用伐鬼方，三年有赏于大国。 ​ <a class="header-anchor" href="#九四-贞吉-悔亡。震用伐鬼方-三年有赏于大国。-​" aria-label="Permalink to “九四：贞吉，悔亡。震用伐鬼方，三年有赏于大国。 ​”">​</a></h2><p>王弼：处未济之时，而出险难之上，居文明之初，体乎刚质，以近至尊。虽履非其位，志在乎正，则吉而悔亡矣。其志得行，靡禁其威，故曰“震用伐鬼方”也。“伐鬼方”者，兴衰之征也。故每至兴衰而取义焉。处文明之初，始出於难，其德未盛，故曰“三年”也。五居尊以柔，体乎文明之盛，不夺物功者也，故以大国赏之也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：居未济之时，履失其位，所以为悔。但出险难之外，居文明之初，以刚健之质，接近至尊，志行其正，正则贞吉而悔亡，故曰贞吉、悔亡。正志既行，靡禁其威，故震发威怒，用伐鬼方也。然处文明之初，始出於险，其德未盛，不能即胜，故曰“三年”也。五以顺柔文明而居尊位，不夺物功。九四既克而还，必得百里大国之赏，故曰“有赏於大国”也。</p><h3 id="《象》曰-贞吉-悔亡-志行也。-​" tabindex="-1">《象》曰：“贞吉，悔亡”，志行也。 ​ <a class="header-anchor" href="#《象》曰-贞吉-悔亡-志行也。-​" aria-label="Permalink to “《象》曰：“贞吉，悔亡”，志行也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志行”者，释九四失位而得“贞吉悔亡”者也。以其正志得行，而终吉故也。</p><h2 id="六五-贞吉-无悔。君子之光-有孚-吉。-​" tabindex="-1">六五：贞吉，无悔。君子之光，有孚，吉。 ​ <a class="header-anchor" href="#六五-贞吉-无悔。君子之光-有孚-吉。-​" aria-label="Permalink to “六五：贞吉，无悔。君子之光，有孚，吉。 ​”">​</a></h2><p>王弼：以柔居尊，处文明之盛，为未济之主，故必正然后乃吉，吉乃得无悔也。夫以柔顺文明之质，居於尊位，付与於能，而不自役，使武以文，御刚以柔，斯诚君子之光也。付物以能，而不疑也，物则竭力，功斯克矣，故曰：“有孚，吉。”</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“贞吉，无悔”者，六五以柔居尊，处文明之盛，为未济之主，故必正然后乃吉，吉乃得无悔，故曰“贞吉，无悔”也。“君子之光”者，以柔顺文明之质，居於尊位，有应於二，是能付物以能，而不自役，有君子之光华矣，故曰“君子之光”也。“有孚，吉”者，付物以能而无疑焉，则物竭其诚，功斯克矣，故曰“有孚，吉”也。</p><h3 id="《象》曰-君子之光-其晖吉也。-​" tabindex="-1">《象》曰：“君子之光”，其晖吉也。 ​ <a class="header-anchor" href="#《象》曰-君子之光-其晖吉也。-​" aria-label="Permalink to “《象》曰：“君子之光”，其晖吉也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“其晖吉”者，言君子之德，光晖著见，然后乃得吉也。</p><h2 id="上九-有孚于饮酒-无咎。濡其首-有孚-失是。-​" tabindex="-1">上九：有孚于饮酒，无咎。濡其首，有孚，失是。 ​ <a class="header-anchor" href="#上九-有孚于饮酒-无咎。濡其首-有孚-失是。-​" aria-label="Permalink to “上九：有孚于饮酒，无咎。濡其首，有孚，失是。 ​”">​</a></h2><p>王弼：未济之极，则反於既济。既济之道，所任者当也。所任者当，则可信之无疑，而已逸焉。故曰“有孚于饮酒，无咎”也。以其能信於物，故得逸豫而不忧於事之废。苟不忧於事之废，而耽於乐之甚，则至于失节矣。由於有孚，失於是矣，故曰“濡其首，有孚，失是”也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“有孚于饮酒，无咎”者，上九居未济之极，则反於既济。既济之道，则所任者当也。所任者当，则信之无疑，故得自逸饮酒而已，故曰“有孚于饮酒，无咎”。“濡其首”者，既得自逸饮酒，而不知其节，则濡首之难，还复及之，故曰“濡其首”也。“有孚，失是”者，言所以濡首之难及之者，良由信任得人，不忧事废，故失於是矣。故曰“有孚，失是”也。</p><h3 id="《象》曰-饮酒-濡首-亦不知节也。-​" tabindex="-1">《象》曰：“饮酒”“濡首”，亦不知节也。 ​ <a class="header-anchor" href="#《象》曰-饮酒-濡首-亦不知节也。-​" aria-label="Permalink to “《象》曰：“饮酒”“濡首”，亦不知节也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“亦不知节”者，释饮酒所以致濡首之难，以其不知止节故也。</p>',70)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
